/* Sahte @minecraft/server-ui.

   ---- NIYE VAR ----
   menu.js bu modulu DINAMIK import ile yukluyor (bilerek:
   modul yoksa paketin tamami olmesin). Testte modul hic
   olmadigi icin menuAc her zaman sessizce false donuyordu ve
   MENUYU GERCEKTEN ACAN tek bir test bile yoktu. v4.94'un
   zirhMenusu cokmesi (TDZ) tam o kor noktada saklandi.

   ---- NIYE ISTEGE BAGLI ----
   Iki test (menu.mjs, gunes.mjs) tam TERSINI sinliyor:
   "modul yokken menu kendini devre disi birakiyor mu".
   O guvence degerli, silinmemeli. Bu yuzden taklit yalniz
   SIMSEK_MENU=1 iken yukleniyor; digerlerinde import
   patliyor ve menu.js'in eski "modul yok" yolu aynen
   sinaniyor.                                                */
if (process.env.SIMSEK_MENU !== "1") {
  throw new Error("@minecraft/server-ui taklidi kapali (SIMSEK_MENU=1 gerek)");
}

export const _menuKayit = { acilan: [], sonForm: null };
export function _menuSifirla() {
  _menuKayit.acilan.length = 0;
  _menuKayit.sonForm = null;
}

export class ActionFormData {
  constructor() { this.baslikMetni = ""; this.govde = ""; this.dugmeler = []; }
  title(t) { this.baslikMetni = t; return this; }
  body(t) { this.govde = t; return this; }
  button(t, ikon) { this.dugmeler.push(t); return this; }
  show(oyuncu) {
    _menuKayit.acilan.push({
      baslik: this.baslikMetni,
      dugmeler: this.dugmeler.slice(),
      form: this
    });
    _menuKayit.sonForm = this;
    const kendi = this;
    return {
      then(cb) { kendi._coz = cb; return { catch() { return this; } }; }
    };
  }
  /* Test tarafi: kullanicinin dugmeye basmasi. */
  sec(i) { if (this._coz) this._coz({ canceled: false, selection: i }); }
  iptal() { if (this._coz) this._coz({ canceled: true, selection: undefined }); }
}
export class MessageFormData {
  constructor() { this.dugmeler = []; }
  title() { return this; } body() { return this; }
  button1(t) { this.dugmeler.push(t); return this; }
  button2(t) { this.dugmeler.push(t); return this; }
  show() { return { then() { return { catch() {} }; } }; }
}
export class ModalFormData {
  title() { return this; } textField() { return this; }
  show() { return { then() { return { catch() {} }; } }; }
}
